  /^(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun) (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) ([ \d]\d) (\d{2}):(\d{2}):(\d{2}) (\d{4})$/;

function hasReadableSseData(block: string): boolean {
  const dataLines = block
    .split(/\r\n|\n|\r/)
    .filter((line) => line === "data" || line.startsWith("data:"))
    .map((line) => {
      if (line === "data") {
        return "";
      }
      const value = line.slice("data:".length);
      return value.startsWith(" ") ? value.slice(1) : value;
    });
  return dataLines.length > 0 && dataLines.join("\n").trim().length > 0;
}

function findSseEventBoundary(buffer: string): { index: number; length: number } | undefined {
  let best: { index: number; length: number } | undefined;
  for (const delimiter of ["\r\n\r\n", "\n\n", "\r\r"]) {
    const index = buffer.indexOf(delimiter);
    if (index === -1) {
      continue;
    }
    if (!best || index < best.index) {
      best = { index, length: delimiter.length };
    }
  }
  return best;
}

function sanitizeOpenAISdkSseResponse(
  response: Response,
  options?: { synthesizeJsonAsSse?: boolean },
): Response {
  const contentType = response.headers.get("content-type") ?? "";
  if (!response.ok || !response.body) {
    return response;
  }
  if (
    options?.synthesizeJsonAsSse === true &&
    (/\bapplication\/json\b/i.test(contentType) || /\+json\b/i.test(contentType))
  ) {
    const source = response.body;
    const decoder = new TextDecoder();
    const encoder = new TextEncoder();
    let reader: ReadableStreamDefaultReader<Uint8Array> | undefined;
    let buffer = "";
    const sseBody = new ReadableStream<Uint8Array>({
      start() {
        reader = source.getReader();
      },
      async pull(controller) {
        try {
          for (;;) {
            const chunk = await reader?.read();
            if (!chunk || chunk.done) {
              buffer += decoder.decode();
              const data = buffer.trim();
              if (data) {
                controller.enqueue(encoder.encode(`data: ${data}\n\n`));
              }
              controller.enqueue(encoder.encode("data: [DONE]\n\n"));
              controller.close();
              return;
            }
            buffer += decoder.decode(chunk.value, { stream: true });
          }
        } catch (error) {
          controller.error(error);
        }
      },
      async cancel(reason) {
        await reader?.cancel(reason);
      },
    });
    const headers = new Headers(response.headers);
    headers.set("content-type", "text/event-stream; charset=utf-8");
    return new Response(sseBody, {
      status: response.status,
      statusText: response.statusText,
      headers,
    });
  }
  if (!/\btext\/event-stream\b/i.test(contentType)) {
    return response;
  }

  const source = response.body;
  const decoder = new TextDecoder();
  const encoder = new TextEncoder();
  let reader: ReadableStreamDefaultReader<Uint8Array> | undefined;
  let buffer = "";

  const enqueueSanitized = (
    controller: ReadableStreamDefaultController<Uint8Array>,
    text: string,
  ): number => {
    let enqueued = 0;
    buffer += text;
    for (;;) {
      const boundary = findSseEventBoundary(buffer);
      if (!boundary) {
        return enqueued;
      }
      const block = buffer.slice(0, boundary.index);
      const separator = buffer.slice(boundary.index, boundary.index + boundary.length);
      buffer = buffer.slice(boundary.index + boundary.length);
      // OpenAI's SDK currently tries to JSON.parse event-only or blank-data SSE
      // messages. Drop those malformed keepalive-style blocks before it parses.
      if (hasReadableSseData(block)) {
        controller.enqueue(encoder.encode(`${block}${separator}`));
        enqueued += 1;
      }
    }
  };

  const sanitizedBody = new ReadableStream<Uint8Array>({
    start() {
      reader = source.getReader();
    },
    async pull(controller) {
      try {
        for (;;) {
          const chunk = await reader?.read();
          if (!chunk || chunk.done) {
            const tail = decoder.decode();
            if (tail) {
              enqueueSanitized(controller, tail);
            }
            if (buffer && hasReadableSseData(buffer)) {
              controller.enqueue(encoder.encode(buffer));
            }
            buffer = "";
            controller.close();
            return;
          }
          const enqueued = enqueueSanitized(
            controller,
            decoder.decode(chunk.value, { stream: true }),
          );
          if (enqueued > 0) {
            return;
          }
        }
      } catch (error) {
        controller.error(error);
      }
    },
    async cancel(reason) {
      await reader?.cancel(reason);
    },
  });

  return new Response(sanitizedBody, {
    status: response.status,
    statusText: response.statusText,
    headers: response.headers,
  });
}

function shouldSanitizeOpenAISdkSseResponse(model: Model): boolean {
  if (model.provider !== "openai") {
    return true;
  }
  try {
    return new URL(model.baseUrl).hostname.toLowerCase() !== "api.openai.com";
  } catch {
    return true;
  }
}

function isJsonContentType(contentType: string): boolean {
  return /\bapplication\/json\b/i.test(contentType) || /\+json\b/i.test(contentType);
}

function isOpenAISdkStreamContentType(contentType: string): boolean {
  return /\btext\/event-stream\b/i.test(contentType) || isJsonContentType(contentType);
}

type OpenAISdkStreamBodyKind = "html" | "json" | "sse" | "unknown";

function classifyOpenAISdkStreamBodyPrefix(text: string): OpenAISdkStreamBodyKind {
  const trimmed = text.replace(/^\uFEFF/u, "").trimStart();
  if (!trimmed) {
    return "unknown";
  }
  if (trimmed.startsWith("<")) {
    return "html";
  }
  if (trimmed.startsWith("{") || trimmed.startsWith("[")) {
    return "json";
  }
  if (/^(?::|(?:data|event|id|retry)(?::|\r?\n|\r))/u.test(trimmed)) {
    return "sse";
  }
  const boundary = findSseEventBoundary(text);
  if (boundary && hasReadableSseData(text.slice(0, boundary.index))) {
    return "sse";
  }
  return "unknown";
}

async function classifyOpenAISdkStreamBody(response: Response): Promise<OpenAISdkStreamBodyKind> {
  const reader = response.clone().body?.getReader();
  if (!reader) {
    return "unknown";
  }

  const decoder = new TextDecoder();
  let total = 0;
  let text = "";
  try {
    while (total < OPENAI_SDK_STREAM_CONTENT_SNIFF_BYTES) {
      const { value, done } = await reader.read();
      if (done) {
        break;
      }
      if (!value || value.byteLength === 0) {
        continue;
      }
      const remaining = OPENAI_SDK_STREAM_CONTENT_SNIFF_BYTES - total;
      const chunk = value.byteLength > remaining ? value.subarray(0, remaining) : value;
      total += chunk.byteLength;
      text += decoder.decode(chunk, { stream: true });
      const kind = classifyOpenAISdkStreamBodyPrefix(text);
      if (kind !== "unknown") {
        return kind;
      }
    }
    text += decoder.decode();
    return classifyOpenAISdkStreamBodyPrefix(text);
  } finally {
    void reader.cancel().catch(() => undefined);
  }
}

function withOpenAISdkStreamContentType(response: Response, contentType: string): Response {
  const headers = new Headers(response.headers);
  headers.set("content-type", contentType);
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

async function normalizeOpenAISdkStreamContentType(params: {
  response: Response;
  model: Model;
  release: () => Promise<void>;
  localServiceLease?: ProviderLocalServiceLease;
}): Promise<Response> {
  const contentType = params.response.headers.get("content-type") ?? "";
  if (!params.response.ok || !params.response.body || isOpenAISdkStreamContentType(contentType)) {
    return params.response;
  }
  if (!contentType.trim()) {
    // ChatGPT Codex can stream valid SSE with no content-type header. Sniff a
    // clone so the SDK still receives the original body once we normalize it.
    const kind = await classifyOpenAISdkStreamBody(params.response).catch(() => "unknown" as const);
    if (kind === "sse") {
      return withOpenAISdkStreamContentType(params.response, "text/event-stream; charset=utf-8");
    }
    if (kind === "json") {
      return withOpenAISdkStreamContentType(params.response, "application/json; charset=utf-8");
    }
  }
  const body = await readResponseTextLimited(params.response).catch(() => "");
  await params.release().catch(() => undefined);
  params.localServiceLease?.release();
  const hint =
    "OpenAI-compatible streamed responses must be text/event-stream or JSON; got " +
    `${contentType || "missing content-type"}. Check the provider baseUrl; ` +
    "OpenAI-compatible APIs commonly require a /v1 path prefix.";
  throw new ProviderHttpError(`${params.model.provider}/${params.model.id}: ${hint}`, {
    status: params.response.status,
    code: "invalid_provider_content_type",
    type: "invalid_response",
    body,
  });
}

async function requestBodyHasStreamTrue(
  request: Request | undefined,
  init: RequestInit | undefined,
): Promise<boolean> {
  const method = request?.method ?? init?.method;
  if (method && method.toUpperCase() !== "POST") {
    return false;
  }
  const headers = request?.headers ?? new Headers(init?.headers);
  const contentType = headers.get("content-type") ?? "";
  if (contentType && !/\bapplication\/json\b/i.test(contentType)) {
    return false;
  }

  let text: string | undefined;
  if (typeof init?.body === "string") {
    text = init.body;
  }
  if (!text) {
    return false;
  }
  try {
    return (JSON.parse(text) as { stream?: unknown }).stream === true;
  } catch {
    return false;
  }
}

function decodeProviderTraceBody(body: BodyInit | null | undefined): string | undefined {
  if (typeof body === "string") {
    return body;
  }
  if (body instanceof ArrayBuffer) {
    return Buffer.from(body).toString("utf8");
  }
  if (ArrayBuffer.isView(body)) {
    return Buffer.from(body.buffer, body.byteOffset, body.byteLength).toString("utf8");
  }
  return undefined;
}

async function readProviderRequestJsonBody(
  request: Request | undefined,
  init: RequestInit | undefined,
): Promise<{ text: string; payload: unknown } | undefined> {
  const headers = request?.headers ?? new Headers(init?.headers);
  const contentType = headers.get("content-type") ?? "";
  if (contentType && !isJsonContentType(contentType)) {
    return undefined;
  }

  let text = decodeProviderTraceBody(init?.body ?? null);
  if (!text && request) {
    try {
      text = await request.clone().text();
    } catch {
      return undefined;
    }
  }
  if (!text?.trim()) {
    return undefined;
  }
  try {
    return { text, payload: JSON.parse(text) as unknown };
  } catch {
    return undefined;
  }
}

function resolveProviderHttpPayloadTraceSource(model: Model, url: string): string {
  let endpoint = "request";
  try {
    const pathname = new URL(url).pathname.toLowerCase();
    if (pathname.endsWith("/chat/completions")) {
      endpoint = "chat-completions";
    } else if (pathname.endsWith("/responses")) {
      endpoint = "responses";
    }
  } catch {
    // Keep the generic endpoint label for non-standard URL strings.
  }
  return `${model.api}-${endpoint}-http`;
}

function parseRetryAfterSeconds(headers: Headers): number | undefined {
  const retryAfterMs = headers.get("retry-after-ms");
  if (retryAfterMs) {
    const trimmedRetryAfterMs = retryAfterMs.trim();
    if (/^\d+(?:\.\d+)?$/.test(trimmedRetryAfterMs)) {
      const milliseconds = asFiniteNumberInRange(parseStrictFiniteNumber(trimmedRetryAfterMs), {
        min: 0,
        max: Number.MAX_SAFE_INTEGER,
      });
      return milliseconds === undefined ? Number.POSITIVE_INFINITY : milliseconds / 1000;
    }
  }

  const retryAfter = headers.get("retry-after");
  if (!retryAfter) {
    return undefined;
  }

  const trimmedRetryAfterSeconds = retryAfter.trim();
  if (/^\d+$/.test(trimmedRetryAfterSeconds)) {
    return parseStrictNonNegativeInteger(trimmedRetryAfterSeconds) ?? Number.POSITIVE_INFINITY;
  }

  const trimmedRetryAfter = trimmedRetryAfterSeconds;
  if (!RETRY_AFTER_HTTP_DATE_RE.test(trimmedRetryAfter)) {
    return undefined;
  }

  const retryAt = parseRetryAfterHttpDateMs(trimmedRetryAfter);
  if (Number.isNaN(retryAt)) {
    return undefined;
  }

  return Math.max(0, (retryAt - Date.now()) / 1000);
}

function parseRetryAfterHttpDateMs(value: string): number {
  const match = OBSOLETE_ASCTIME_HTTP_DATE_RE.exec(value);
  if (match) {
    const month = HTTP_DATE_MONTH_INDEX.get(match[1] ?? "");
    if (month === undefined) {
      return Number.NaN;
    }
    const year = Number.parseInt(match[6] ?? "", 10);
    const day = Number.parseInt((match[2] ?? "").trim(), 10);
    const hours = Number.parseInt(match[3] ?? "", 10);
    const minutes = Number.parseInt(match[4] ?? "", 10);
    const seconds = Number.parseInt(match[5] ?? "", 10);
    if (
      day < 1 ||
      day > 31 ||
      hours > 23 ||
      minutes > 59 ||
      seconds > 59 ||
      [year, day, hours, minutes, seconds].some((component) => !Number.isFinite(component))
    ) {
      return Number.NaN;
    }
    const timestamp = Date.UTC(year, month, day, hours, minutes, seconds);
    const parsedDate = new Date(timestamp);
    return parsedDate.getUTCFullYear() === year &&
      parsedDate.getUTCMonth() === month &&
      parsedDate.getUTCDate() === day &&
      parsedDate.getUTCHours() === hours &&
      parsedDate.getUTCMinutes() === minutes &&
      parsedDate.getUTCSeconds() === seconds
      ? timestamp
      : Number.NaN;
  }

  const parsed = Date.parse(value);
  if (!Number.isNaN(parsed)) {
    return parsed;
  }
  return Number.NaN;
}

function resolveMaxSdkRetryWaitSeconds(): number | undefined {
  const raw = process.env.OPENCLAW_SDK_RETRY_MAX_WAIT_SECONDS?.trim();
  if (!raw) {
    return DEFAULT_MAX_SDK_RETRY_WAIT_SECONDS;
  }

  if (/^(?:0|false|off|none|disabled)$/i.test(raw)) {
    return undefined;
  }

  if (!PLAIN_DECIMAL_NUMBER_RE.test(raw)) {
    return DEFAULT_MAX_SDK_RETRY_WAIT_SECONDS;
  }

  const seconds = asFiniteNumberInRange(parseStrictFiniteNumber(raw), {
    min: 0,
    minExclusive: true,
    max: Number.MAX_SAFE_INTEGER,
  });
  if (seconds !== undefined) {
    return seconds;
  }

  return DEFAULT_MAX_SDK_RETRY_WAIT_SECONDS;
}

function shouldBypassLongSdkRetry(response: Response): boolean {
  const maxWaitSeconds = resolveMaxSdkRetryWaitSeconds();
  if (maxWaitSeconds === undefined) {
    return false;
  }

  const status = response.status;
  const stainlessRetryable = status === 408 || status === 409 || status === 429 || status >= 500;
  if (!stainlessRetryable) {
    return false;
  }

  const retryAfterSeconds = parseRetryAfterSeconds(response.headers);
  if (retryAfterSeconds !== undefined) {
    return retryAfterSeconds > maxWaitSeconds;
  }

  return status === 429;
}

const managedStreamCleanupRegistry = new FinalizationRegistry<{ finalize: () => Promise<void> }>(
  (held) => {
    void held.finalize();
  },
);

function buildManagedResponse(
  response: Response,
  release: () => Promise<void>,
  refreshTimeout?: () => void,
  localServiceLease?: ProviderLocalServiceLease,
): Response {
  const finalizeLocalServiceLease = () => {
    localServiceLease?.release();
  };
  if (!response.body) {
    void release().finally(finalizeLocalServiceLease);
    return response;
  }
  const source = response.body;
  let reader: ReadableStreamDefaultReader<Uint8Array> | undefined;
  let released = false;
  const cleanupRegistrationToken = {};
  const finalize = async () => {
    if (released) {
      return;
    }
    released = true;
    managedStreamCleanupRegistry.unregister(cleanupRegistrationToken);
    try {
      await reader?.cancel().catch(() => undefined);
      await release().catch(() => undefined);
    } finally {
      finalizeLocalServiceLease();
    }
  };
  const wrappedBody = new ReadableStream<Uint8Array>({
    start() {
      reader = source.getReader();
    },
    async pull(controller) {
      try {
        const chunk = await reader?.read();
        if (!chunk || chunk.done) {
          controller.close();
          await finalize();
          return;
        }
        refreshTimeout?.();
        controller.enqueue(chunk.value);
      } catch (error) {
        controller.error(error);
        await finalize();
      }
    },
    async cancel(reason) {
      try {
        await reader?.cancel(reason);
      } finally {
        await finalize();
      }
    },
  });
  // Stream consumers should cancel deterministically; this catches abandoned
  // wrapper bodies so guarded dispatchers and local-service leases do not leak.
  managedStreamCleanupRegistry.register(wrappedBody, { finalize }, cleanupRegistrationToken);
  return new Response(wrappedBody, {
    status: response.status,
    statusText: response.statusText,
    headers: response.headers,
  });
}

function resolveModelRequestPolicy(model: Model) {
  const debugProxy = resolveDebugProxySettings();
  let explicitDebugProxyUrl: string | undefined;
  if (debugProxy.enabled && debugProxy.proxyUrl) {
    try {
      if (new URL(model.baseUrl).protocol === "https:") {
        explicitDebugProxyUrl = debugProxy.proxyUrl;
      }
    } catch {
      // Non-URL provider base URLs cannot use the debug proxy override safely.
    }
  }
  const request = mergeModelProviderRequestOverrides(getModelProviderRequestTransport(model), {
    proxy: explicitDebugProxyUrl
      ? {
          mode: "explicit-proxy",
          url: explicitDebugProxyUrl,
        }
      : undefined,
  });
  return resolveProviderRequestPolicyConfig({
    provider: model.provider,
    api: model.api,
    baseUrl: model.baseUrl,
    capability: "llm",
    transport: "stream",
    request,
  });
}

export function resolveModelRequestTimeoutMs(
  model: Model,
  timeoutMs: number | undefined,
): number | undefined {
  if (timeoutMs !== undefined) {
    return typeof timeoutMs === "number" && Number.isFinite(timeoutMs) && timeoutMs > 0
      ? clampTimerTimeoutMs(timeoutMs)
      : undefined;
  }
  const modelTimeoutMs = (model as { requestTimeoutMs?: unknown }).requestTimeoutMs;
  return typeof modelTimeoutMs === "number" && Number.isFinite(modelTimeoutMs) && modelTimeoutMs > 0
    ? clampTimerTimeoutMs(modelTimeoutMs)
    : undefined;
}

function buildModelRequestSignal(
  baseSignal: AbortSignal | undefined,
  timeoutMs: number | undefined,
): AbortSignal | undefined {
  if (timeoutMs === undefined) {
    return baseSignal;
  }
  const timeoutSignal = AbortSignal.timeout(timeoutMs);
  if (!baseSignal) {
    return timeoutSignal;
  }
  return AbortSignal.any([baseSignal, timeoutSignal]);
}

function resolveHttpOrigin(value: unknown): string | undefined {
  if (typeof value !== "string" || !value.trim()) {
    return undefined;
  }
  try {
    const parsed = new URL(value);
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
      return undefined;
    }
    parsed.hostname = parsed.hostname.replace(/\.+$/, "");
    return parsed.origin.toLowerCase();
  } catch {
    return undefined;
  }
}

function normalizeProviderOriginHostname(value: unknown): string | undefined {
  if (typeof value !== "string" || !value.trim()) {
    return undefined;
  }
  try {
    const parsed = new URL(value);
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
      return undefined;
    }
    const normalized = parsed.hostname.trim().toLowerCase().replace(/\.+$/, "");
    return normalized || undefined;
  } catch {
    return undefined;
  }
}

function canImplicitlyTrustConfiguredBaseUrlOrigin(value: unknown): value is string {
  const hostname = normalizeProviderOriginHostname(value);
  if (!hostname) {
    return false;
  }
  const labels = hostname.split(".").filter(Boolean);
  return (
    !labels.some(
      (label) =>
        label.includes("metadata") || BLOCKED_EXACT_ORIGIN_TRUST_HOSTNAME_LABELS.has(label),
    ) &&
    !isLinkLocalIpAddress(hostname) &&
    !isCloudMetadataIpAddress(hostname)
  );
}

function canApplyFakeIpHostnamePolicy(value: unknown): value is string {
  const hostname = normalizeProviderOriginHostname(value);
  if (!hostname) {
    return false;
  }
  const labels = hostname.split(".").filter(Boolean);
  return (
    !labels.some(
      (label) =>
        label.includes("metadata") || BLOCKED_EXACT_ORIGIN_TRUST_HOSTNAME_LABELS.has(label),
    ) && !parseCanonicalIpAddress(hostname)
  );
}

function resolveModelTransportSsrFPolicy(params: {
  model: Model;
  url: string;
  allowPrivateNetwork?: boolean;
  trustConfiguredBaseUrlOrigin?: boolean;
}): SsrFPolicy | undefined {
  const baseUrl = (params.model as { baseUrl?: unknown }).baseUrl;
  const baseOrigin = resolveHttpOrigin(baseUrl);
  const requestOrigin = resolveHttpOrigin(params.url);
  const requestMatchesBaseOrigin =
    typeof baseUrl === "string" && Boolean(baseOrigin) && requestOrigin === baseOrigin;
  const baseUrlOriginPolicy =
    requestMatchesBaseOrigin &&
    params.trustConfiguredBaseUrlOrigin &&
    canImplicitlyTrustConfiguredBaseUrlOrigin(baseUrl)
      ? ssrfPolicyFromHttpBaseUrlAllowedOrigin(baseUrl)
      : undefined;
  // Fake-IP trust is hostname-scoped and orthogonal to exact-origin private-IP trust.
  // It is for DNS hostnames only and does not allow literal private IPs by itself.
  const fakeIpPolicy =
    requestMatchesBaseOrigin && canApplyFakeIpHostnamePolicy(baseUrl)
      ? ssrfPolicyFromHttpBaseUrlFakeIpHostnameAllowlist(baseUrl)
      : undefined;
  return mergeSsrFPolicies(
    baseUrlOriginPolicy,
    fakeIpPolicy,
    params.allowPrivateNetwork ? { allowPrivateNetwork: true } : undefined,
  );
}

export function buildGuardedModelFetch(
  model: Model,
  timeoutMs?: number,
  options?: { sanitizeSse?: boolean },
  shadow?: ShadowReceiptOptions,
): typeof fetch {
  const requestConfig = resolveModelRequestPolicy(model);
  const dispatcherPolicy = buildProviderRequestDispatcherPolicy(requestConfig);
  const requestTimeoutMs = resolveModelRequestTimeoutMs(model, timeoutMs);
  // Quota identity is stable per model+credential; resolving it once per guarded fetch keeps the
  // per-attempt cost to one gate lookup.
  const outboundGroup = resolveProviderOutboundQuotaGroup({ model, requestConfig });
  let nextWireAttemptIndex = shadow?.wireAttemptIndex ?? 0;
  const summarizeError = (error: unknown): string => {
    if (!error || typeof error !== "object") {
      return `type=${typeof error}`;
    }
    const record = error as Record<string, unknown>;
    const cause =
      record.cause && typeof record.cause === "object"
        ? (record.cause as Record<string, unknown>)
        : undefined;
    const read = (value: unknown) => (typeof value === "string" ? value : typeof value);
    return [
      `name=${read(record.name)}`,
      `code=${read(record.code)}`,
      `causeName=${read(cause?.name)}`,
      `causeCode=${read(cause?.code)}`,
      `message=${error instanceof Error ? error.message : read(record.message)}`,
    ].join(" ");
  };
  return async (input, init) => {
    let localServiceLease: ProviderLocalServiceLease | undefined;
    const request = input instanceof Request ? new Request(input, init) : undefined;
    const url = appendProviderRequestAuthQuery(
      request?.url ??
        (input instanceof URL
          ? input.toString()
          : typeof input === "string"
            ? input
            : (() => {
                throw new Error("Unsupported fetch input for transport-aware model request");
              })()),
      requestConfig.auth,
    );
    const policy = resolveModelTransportSsrFPolicy({
      model,
      url,
      allowPrivateNetwork: requestConfig.allowPrivateNetwork,
      // Only operator-configured custom/local endpoints get exact-origin trust;
      // known public/native providers keep the default rebinding checks.
      trustConfiguredBaseUrlOrigin:
        !requestConfig.privateNetworkExplicitlyDenied &&
        (requestConfig.policy?.endpointClass === "custom" ||
          requestConfig.policy?.endpointClass === "local"),
    });
    const requestInit =
      request &&
      ({
        method: request.method,
        headers: request.headers,
        body: request.body ?? undefined,
        redirect: request.redirect,
        signal: request.signal,
        ...(request.body ? ({ duplex: "half" } as const) : {}),
      } satisfies RequestInit & { duplex?: "half" });
    const baseInit = requestInit ?? init;
    const shouldReadProviderBody = Boolean(shadow) || isProviderPayloadTraceEnabled();
    const providerBody = shouldReadProviderBody
      ? await readProviderRequestJsonBody(request, baseInit)
      : undefined;
    if (isProviderPayloadTraceEnabled() && providerBody !== undefined) {
      recordProviderPayloadTrace(
        undefined,
        providerBody.payload,
        resolveProviderHttpPayloadTraceSource(model, url),
      );
    }
    if (shadow) {
      const wireAttemptIndex = nextWireAttemptIndex;
      nextWireAttemptIndex += 1;
      let wireShadow: ShadowReceiptOptions = { ...shadow, wireAttemptIndex };
      if (providerBody) {
        // Stage 1 observational envelope. Digest/ref only; request bytes do not change.
        const endpointClass =
          requestConfig.policy?.endpointClass === "custom"
            ? "custom"
            : requestConfig.policy?.endpointClass === "local"
              ? "local"
              : "public";
        const envelope = buildStage1RequestEnvelope({
          body: providerBody.payload,
          bodyText: providerBody.text,
          providerId: model.provider,
          adapterId: model.api,
          modelId: model.id,
          url,
          method: request?.method ?? baseInit?.method ?? "POST",
          endpointClass,
          wireAttemptIndex,
          shadow: wireShadow,
        });
        if (envelope.ok) {
          wireShadow = { ...wireShadow, requestEnvelopeRef: envelope.envelopeRef };
        } else {
          recordShadowCensusFailure(
            "wire-capture",
            envelope.reason === "unregistered-transform"
              ? "unregistered-transform"
              : "request-envelope-incomplete",
          );
        }
        // Receipt writes are observational. A persistence failure is recorded by the
        // census diagnostics, while the guarded provider request continues unchanged.
        emitShadowWireReceipt(
          providerBody.text,
          {
            providerId: model.provider,
            adapterId: model.api,
            modelId: model.id,
            sessionKey: wireShadow.sessionKey,
            runId: wireShadow.runId,
            traceId: wireShadow.traceId,
            transformIds: wireShadow.transformIds,
            attemptIndex: wireShadow.attemptIndex,
            modelCallIndex: wireShadow.modelCallIndex,
            wireAttemptIndex,
          },
          wireShadow,
        );
        if (wireShadow.rc03Plan) {
          // RC-03: WireReceipt/v1 at the guarded request boundary, bound to the
          // sealed CompilePlan and the final serialized body digest. Observational:
          // failures land in the census diagnostics, never in the send path.
          emitRc03WireReceipt(providerBody.text, wireShadow, {
            providerId: model.provider,
            adapterId: model.api,
            modelId: model.id,
            wireAttemptIndex,
          });
        }
      } else {
        recordShadowCensusFailure("wire-capture", "final-wire-body-unavailable");
      }
    }
    const synthesizeJsonAsSse = await requestBodyHasStreamTrue(request, baseInit);
    const baseSignal = baseInit?.signal ?? undefined;
    const localServiceSignal = buildModelRequestSignal(baseSignal, requestTimeoutMs);
    const guardedFetchOptions = {
      url,
      init: baseInit,
      capture: {
        meta: {
          provider: model.provider,
          api: model.api,
          model: model.id,
        },
      },
      dispatcherPolicy,
      timeoutMs: requestTimeoutMs,
      // Model requests target operator-configured provider endpoints. Connection-time
      // DNS pinning stalls streamed SSE responses through the custom pinned dispatcher
      // (the resolve-time hostname/IP SSRF policy check still runs via pinDns=false),
      // so model transport uses a non-pinned dispatcher to keep streaming reliable.
      pinDns: false as const,
      ...(baseSignal ? { signal: baseSignal } : {}),
      // Provider transport intentionally keeps the secure default and never
      // replays unsafe request bodies across cross-origin redirects.
      allowCrossOriginUnsafeRedirectReplay: false,
      ...(policy ? { policy } : {}),
    };
    let result: Awaited<ReturnType<typeof fetchWithSsrFGuard>>;
    const fetchStartedAt = Date.now();
    const useEnvProxy = !dispatcherPolicy && shouldUseEnvHttpProxyForUrl(url);
    // Shared outbound concurrency budget (issue #154). Admission happens before the local
    // provider sidecar starts and before any bytes go on the wire, so a refused request never
    // enters the expensive path. The slot is released only where the guarded request is
    // confirmed finished — stream end, stream cancel, error, or dispatcher release — never by an
    // upper-layer timeout that leaves the physical request alive.
    const admission = await acquireProviderOutboundSlot({
      group: outboundGroup,
      ...(baseSignal ? { signal: baseSignal } : {}),
    });
    if (!admission.ok) {
      throw new ProviderOutboundOverloadedError({
        model,
        reason: admission.reason,
        endpoint: outboundGroup.endpoint,
        waitedMs: admission.waitedMs,
        snapshot: admission.snapshot,
      });
    }
    const outboundSlot = admission.slot;
    let outboundSlotReleased = false;
    const releaseOutboundSlot = (): boolean => {
      if (outboundSlotReleased) {
        return false;
      }
      outboundSlotReleased = true;
      return outboundSlot.release();
    };
    const releaseGuardedRequest = async (): Promise<void> => {
      try {
        await result.release();
      } finally {
        releaseOutboundSlot();
      }
    };
    emitModelTransportDebug(
      log,
      `[model-fetch] start provider=${model.provider} api=${model.api} model=${model.id} ` +
        `method=${baseInit?.method ?? "GET"} url=${formatModelTransportDebugUrl(url)} timeoutMs=${requestTimeoutMs} ` +
        `proxy=${dispatcherPolicy ? "configured" : useEnvProxy ? "env" : "none"} ` +
        `policy=${policy ? "custom" : "default"} ` +
        `outbound=${outboundSlot.limited ? "gated" : "ungated"} admissionWaitMs=${outboundSlot.waitedMs}`,
    );
    try {
      localServiceLease = await ensureModelProviderLocalService(
        model,
        baseInit?.headers,
        localServiceSignal,
      );
      result = await fetchWithSsrFGuard(
        useEnvProxy
          ? withTrustedEnvProxyGuardedFetchMode(guardedFetchOptions)
          : guardedFetchOptions,
      );
    } catch (error) {
      log.warn(
        `[model-fetch] error provider=${model.provider} api=${model.api} model=${model.id} ` +
          `elapsedMs=${Date.now() - fetchStartedAt} ${summarizeError(error)}`,
      );
      localServiceLease?.release();
      releaseOutboundSlot();
      throw error;
    }
    let response = result.response;
    emitModelTransportDebug(
      log,
      `[model-fetch] response provider=${model.provider} api=${model.api} model=${model.id} ` +
        `status=${response.status} elapsedMs=${Date.now() - fetchStartedAt} ` +
        `contentType=${response.headers.get("content-type") ?? ""}`,
    );
    if (shouldBypassLongSdkRetry(response)) {
      const headers = new Headers(response.headers);
      headers.set("x-should-retry", "false");
      response = new Response(response.body, {
        status: response.status,
        statusText: response.statusText,
        headers,
      });
    }
    if (synthesizeJsonAsSse && options?.sanitizeSse !== false) {
      response = await normalizeOpenAISdkStreamContentType({
        response,
        model,
        release: releaseGuardedRequest,
        localServiceLease,
      });
    }
    response = buildManagedResponse(
      response,
      releaseGuardedRequest,
      result.refreshTimeout,
      localServiceLease,
    );
    return options?.sanitizeSse === false || !shouldSanitizeOpenAISdkSseResponse(model)
      ? response
      : sanitizeOpenAISdkSseResponse(response, { synthesizeJsonAsSse });
  };
}

// RC-08B correlation IDs. Ingress, run, model/tool, effect, and delivery share a
// stable correlation identity so OTel/OTLP spans link across the runtime flow.
// Receipts and domain journals remain factual evidence; correlation IDs only
// join them — they never replace the journals.
import { createHash } from 'node:crypto';

export const CORRELATION_SCHEMA_VERSION = '1';

export type CorrelationSegments = {
  ingressId?: string;
  runId?: string;
  modelCallId?: string;
  effectId?: string;
  deliveryId?: string;
};

export type CorrelationIdentity = {
  /** Stable correlation digest across all segments. */
  correlationDigest: string;
  segments: CorrelationSegments;
};

/**
 * Build a stable correlation digest from the joined segments. The same set of
 * segments yields the same digest (used as the OTel traceId root).
 */
export function correlationDigest(segments: CorrelationSegments): string {
  return createHash('sha256')
    .update(
      [
        segments.ingressId ?? '',
        segments.runId ?? '',
        segments.modelCallId ?? '',
        segments.effectId ?? '',
        segments.deliveryId ?? '',
      ].join(''),
    )
    .digest('hex');
}

/**
 * R5-3: canonical stable-JSON hasher shared with the receipt correlation
 * digests (shadow-census), so RC-08B correlation ids and receipt
 * correlation_digest values hash through one module/source.
 */
export function digestStableJson(value: unknown): string {
  return createHash('sha256').update(JSON.stringify(value ?? null)).digest('hex');
}

export function buildCorrelationIdentity(segments: CorrelationSegments): CorrelationIdentity {
  return { correlationDigest: correlationDigest(segments), segments };
}

/** A valid OTel trace id is 32 hex chars; the digest is truncated to fit. */
export function toOtelTraceId(correlationDigest: string): string {
  return correlationDigest.slice(0, 32);
}

/** A valid OTel span id is 16 hex chars. */
export function toOtelSpanId(digest: string, salt = 'span'): string {
  return createHash('sha256').update(`${salt}:${digest}`).digest('hex').slice(0, 16);
}

// RC-02 receipt persistence owner: a narrow ReceiptStore interface over a typed,
// append-only runtime_receipts table in the existing openclaw-state SQLite
// (user-confirmed decision 2026-08-02). Seven hard constraints are enforced:
//  1. digest/refs/call-index/version/policy-digest only; never raw payload.
//  2. append-only; same idempotency_key with identical content is idempotent
//     success, different content must conflict-fail.
//  3. explicit attempt/model-call/wire-attempt identity (no max(sequence)+1).
//  4. no silent pruning; deletion requires an explicit lifecycle policy call.
//  5. shadow write failure must not change send behavior but must fail RC-02
//     acceptance (callers surface appendFailure; the shadow path never throws
//     into the send path).
//  6. a receipt explains and correlates facts only; it never authorizes replay;
//     domain journals remain the effect/idempotency truth.
//  7. the npm fallback reports degraded and never counts toward coverage.
import { createHash, randomUUID } from "node:crypto";

import type { Insertable, Selectable } from "kysely";

import {
  getNodeSqliteKysely,
  executeSqliteQuerySync,
  executeSqliteQueryTakeFirstSync,
} from "../infra/kysely-sync.js";
import {
  openOpenClawStateDatabase,
  runOpenClawStateWriteTransaction,
  type OpenClawStateDatabaseOptions,
} from "../state/openclaw-state-db.js";
import type { DB as OpenClawStateKyselyDatabase } from "../state/openclaw-state-db.generated.js";

export const RUNTIME_RECEIPTS_SCHEMA_VERSION = "1";
export const RUNTIME_RECEIPTS_OWNER = "openclaw_runtime.agents.receipt-store";

export const RUNTIME_RECEIPT_KINDS = [
  "shadow_context",
  "shadow_wire",
  "context",
  "wire",
  "effect",
] as const;
export type RuntimeReceiptKind = (typeof RUNTIME_RECEIPT_KINDS)[number];

export const RUNTIME_RECEIPT_RUNTIME_MODES = ["source", "npm"] as const;
export type RuntimeReceiptRuntimeMode = (typeof RUNTIME_RECEIPT_RUNTIME_MODES)[number];

export type RuntimeReceiptInsert = Insertable<OpenClawStateKyselyDatabase["runtime_receipts"]>;
export type RuntimeReceiptRow = Selectable<OpenClawStateKyselyDatabase["runtime_receipts"]>;
export type RuntimeReceiptDatabase = Pick<OpenClawStateKyselyDatabase, "runtime_receipts">;

/** R5-3: one correlated v1 ContextReceipt + WireReceipt pair sharing a correlation_digest. */
export type RuntimeReceiptPair = {
  correlationDigest: string;
  context: RuntimeReceiptRow;
  wire: RuntimeReceiptRow;
};

export type ReceiptIdentity = {
  /** Session key, when the call is bound to a session. */
  sessionKey?: string;
  /** Run id, when the call is bound to a run. */
  runId?: string;
  /** Trace id, when a trace correlation id is available. */
  traceId?: string;
  /** Provider id (e.g. anthropic). */
  providerId?: string;
  /** Adapter id, when a provider-specific adapter performed the finalizers. */
  adapterId?: string;
  /** Registered non-semantic transport transform ids applied after seal. */
  transformIds?: string[];
  /** Runtime mode: source openclaw_runtime or npm fallback. */
  runtimeMode: RuntimeReceiptRuntimeMode;
};

export type ReceiptCallIndex = {
  attemptIndex: number;
  modelCallIndex: number;
  wireAttemptIndex: number;
};

export type ReceiptBudget =
  | {
      unit: "tokens";
      inputLimit: number;
      outputLimit: number;
    }
  | {
      unit: "chars";
      charsRequested: number;
      charsApplied: number;
    };

export type ReceiptCandidateDisposition =
  | "applied"
  | "truncate"
  | "drop"
  | "skip"
  | "duplicate"
  | "pending";

export type ReceiptCandidateReason =
  | "collected"
  | "applied"
  | "duplicate"
  | "empty"
  | "budget-truncate"
  | "budget-drop"
  | "flag-off"
  | "kill-switch"
  | "stale-history"
  | "skip-channel";

/** Bounded, payload-free projection of one candidate decision. */
export type ReceiptCandidateDecision = {
  /** Canonical receipt ref for the candidate. Never the raw candidate id. */
  ref: string;
  /** Public producer label, not authority content or payload. */
  sourceId: string;
  channel: string;
  disposition: ReceiptCandidateDisposition;
  reason: ReceiptCandidateReason;
  charsRequested: number;
  charsApplied: number;
};

/** Candidate decisions persisted with a receipt. `complete:false` means the
 * bounded projection was truncated and the receipt must not claim full coverage. */
export type ReceiptCandidateDecisions = {
  complete: boolean;
  decisions: ReceiptCandidateDecision[];
};

export type ReceiptContent = {
  /** Semantic logical digest (ContextReceipt) or final wire digest (WireReceipt). */
  logicalDigest?: string;
  /** Final request-body digest after provider-specific finalizers. */
  wireDigest?: string;
  /** Correlates the logical and wire receipts of the same model call. */
  correlationDigest: string;
  /** Selected items/decisions projection (JSON array of refs). */
  selected?: string[];
  /** Omitted items/decisions projection (JSON array of refs). */
  omitted?: string[];
  /** Bounded per-candidate disposition/reason projection. */
  candidateDecisions?: ReceiptCandidateDecisions;
  /** Bounded token-budget summary. */
  budget?: ReceiptBudget;
  /** Policy digest (the selection/budget policy that produced this receipt). */
  policyDigest?: string;
};

export type PutReceiptInput = {
  /** Stable idempotency key. Re-applying the same key with identical content is
   *  an idempotent success; different content under the same key must conflict. */
  idempotencyKey: string;
  kind: RuntimeReceiptKind;
  version: string;
  identity: ReceiptIdentity;
  callIndex: ReceiptCallIndex;
  content: ReceiptContent;
  createdAt?: number;
};

export type PutReceiptResult =
  | { ok: true; duplicate: false; receiptId: string; inserted: true }
  | { ok: true; duplicate: true; receiptId: string; inserted: false; reason: "identical-content" }
  | {
      ok: false;
      duplicate: true;
      receiptId: string;
      inserted: false;
      reason: "content-conflict";
      existing: string;
    };

const PUT_RECEIPT_KEYS = new Set([
  "idempotencyKey",
  "kind",
  "version",
  "identity",
  "callIndex",
  "content",
  "createdAt",
]);
const RECEIPT_IDENTITY_KEYS = new Set([
  "sessionKey",
  "runId",
  "traceId",
  "providerId",
  "adapterId",
  "transformIds",
  "runtimeMode",
]);
const RECEIPT_CALL_INDEX_KEYS = new Set(["attemptIndex", "modelCallIndex", "wireAttemptIndex"]);
const RECEIPT_CONTENT_KEYS = new Set([
  "logicalDigest",
  "wireDigest",
  "correlationDigest",
  "selected",
  "omitted",
  "candidateDecisions",
  "budget",
  "policyDigest",
]);
const RECEIPT_CANDIDATE_DECISION_KEYS = new Set([
  "ref",
  "sourceId",
  "channel",
  "disposition",
  "reason",
  "charsRequested",
  "charsApplied",
]);
const RECEIPT_CANDIDATE_DECISIONS_KEYS = new Set(["complete", "decisions"]);
const RECEIPT_CANDIDATE_DISPOSITIONS = new Set<ReceiptCandidateDisposition>([
  "applied",
  "truncate",
  "drop",
  "skip",
  "duplicate",
  "pending",
]);
const RECEIPT_CANDIDATE_REASONS = new Set<ReceiptCandidateReason>([
  "collected",
  "applied",
  "duplicate",
  "empty",
  "budget-truncate",
  "budget-drop",
  "flag-off",
  "kill-switch",
  "stale-history",
  "skip-channel",
]);
const RECEIPT_BUDGET_KEYS = new Set([
  "unit",
  "inputLimit",
  "outputLimit",
  "charsRequested",
  "charsApplied",
]);
const SHA256_DIGEST_RE = /^[a-f0-9]{64}$/;
const RECEIPT_ID_RE = /^[A-Za-z0-9][A-Za-z0-9._:@/-]*$/;
const RECEIPT_CANDIDATE_CHANNEL_RE = /^[a-z][a-z0-9_-]{0,63}$/;
// IRC channel routes contain # (agent:main:irc:group:#channel). Other receipt
// identifiers remain on the stricter grammar; whitespace/control bytes stay invalid.
const RECEIPT_SESSION_KEY_RE = /^[A-Za-z0-9][A-Za-z0-9._:@/#-]*$/;
const RECEIPT_REFERENCE_RE =
  /^(?:ref:(?:context|file|memory|message|tool|request-envelope|compilation-snapshot|prompt-plan):[A-Za-z0-9][A-Za-z0-9._:@/+%-]*|owner-census:v0:[1-9]\d{0,5}:[a-f0-9]{64})$/;
const MAX_IDEMPOTENCY_KEY_LENGTH = 512;
const MAX_IDENTITY_LENGTH = 256;
const MAX_TRANSFORM_ID_LENGTH = 128;
const MAX_TRANSFORM_IDS = 32;
const MAX_RECEIPT_REFERENCES = 64;
const MAX_RECEIPT_REFERENCE_LENGTH = 256;
const MAX_RECEIPT_CANDIDATE_DECISIONS = 64;
const MAX_RECEIPT_CANDIDATE_SOURCE_LENGTH = 128;
const MAX_BUDGET_TOKENS = 1_000_000_000;
const MAX_CALL_INDEX = 2_147_483_647;

const RECEIPT_VERSIONS = {
  shadow_context: "0",
  shadow_wire: "0",
  context: "1",
  wire: "1",
  effect: "1",
} as const satisfies Record<RuntimeReceiptKind, string>;

function assertPlainRecord(
  value: unknown,
  label: string,
): asserts value is Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${label} must be a plain object`);
  }
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null) {
    throw new TypeError(`${label} must use a plain object prototype`);
  }
}

function assertOnlyKeys(value: Record<string, unknown>, keys: Set<string>, label: string): void {
  for (const key of Reflect.ownKeys(value)) {
    if (typeof key !== "string") throw new TypeError(`${label} contains unsupported symbol field`);
    if (!keys.has(key)) throw new TypeError(`${label} contains unsupported field: ${key}`);
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (!descriptor?.enumerable || !("value" in descriptor)) {
      throw new TypeError(`${label} field ${key} must be an enumerable data property`);
    }
  }
}

function assertOptionalId(value: unknown, label: string, pattern = RECEIPT_ID_RE): void {
  if (value === undefined) return;
  if (
    typeof value !== "string" ||
    value.length === 0 ||
    value.length > MAX_IDENTITY_LENGTH ||
    !pattern.test(value)
  ) {
    throw new TypeError(`${label} must be a bounded canonical identifier`);
  }
}

function assertCanonicalStringArray(
  value: unknown,
  label: string,
  options: { maxItems: number; maxLength: number; pattern: RegExp },
): void {
  if (value === undefined) return;
  if (!Array.isArray(value) || Object.getPrototypeOf(value) !== Array.prototype) {
    throw new TypeError(`${label} must be an array of strings when provided`);
  }
  if (value.length > options.maxItems) {
    throw new TypeError(`${label} exceeds the maximum item count`);
  }
  const unique = new Set<string>();
  for (let index = 0; index < value.length; index += 1) {
    const item = value[index];
    if (
      !Object.hasOwn(value, index) ||
      typeof item !== "string" ||
      item.length === 0 ||
      item.length > options.maxLength ||
      !options.pattern.test(item)
    ) {
      throw new TypeError(`${label} must be a dense array of strings when provided`);
    }
    if (unique.has(item)) throw new TypeError(`${label} must not contain duplicate values`);
    unique.add(item);
  }
  for (const key of Reflect.ownKeys(value)) {
    if (key === "length") continue;
    if (typeof key !== "string" || !/^(?:0|[1-9]\d*)$/.test(key) || Number(key) >= value.length) {
      throw new TypeError(`${label} contains unsupported array field: ${String(key)}`);
    }
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (!descriptor?.enumerable || !("value" in descriptor)) {
      throw new TypeError(`${label} array entries must be enumerable data properties`);
    }
  }
}

function assertNonNegativeInteger(value: unknown, label: string): void {
  if (!Number.isSafeInteger(value) || Number(value) < 0 || Number(value) > MAX_CALL_INDEX) {
    throw new TypeError(`${label} must be a bounded non-negative integer`);
  }
}

function assertDigest(value: unknown, label: string, required: boolean): void {
  if (value === undefined && !required) return;
  if (typeof value !== "string" || !SHA256_DIGEST_RE.test(value)) {
    throw new TypeError(`${label} must be a lowercase SHA-256 digest`);
  }
}

function assertBudget(value: unknown, label: string): asserts value is ReceiptBudget | undefined {
  if (value === undefined) return;
  assertPlainRecord(value, label);
  assertOnlyKeys(value, RECEIPT_BUDGET_KEYS, label);
  if (value.unit === "tokens") {
    for (const key of ["inputLimit", "outputLimit"] as const) {
      const amount = value[key];
      if (
        !Number.isSafeInteger(amount) ||
        Number(amount) < 0 ||
        Number(amount) > MAX_BUDGET_TOKENS
      ) {
        throw new TypeError(`${label} ${key} must be a bounded non-negative integer`);
      }
    }
    return;
  }
  if (value.unit === "chars") {
    for (const key of ["charsRequested", "charsApplied"] as const) {
      const amount = value[key];
      if (
        !Number.isSafeInteger(amount) ||
        Number(amount) < 0 ||
        Number(amount) > MAX_BUDGET_TOKENS
      ) {
        throw new TypeError(`${label} ${key} must be a bounded non-negative integer`);
      }
    }
    return;
  }
  throw new TypeError(`${label} unit must be tokens or chars`);
}

function serializeBudget(value: ReceiptBudget | undefined): string | null {
  if (!value) return null;
  if (value.unit === "chars") {
    return JSON.stringify({
      unit: value.unit,
      charsRequested: value.charsRequested,
      charsApplied: value.charsApplied,
    });
  }
  return JSON.stringify({
    unit: value.unit,
    inputLimit: value.inputLimit,
    outputLimit: value.outputLimit,
  });
}

function assertCandidateDecisions(
  value: unknown,
  label: string,
): asserts value is ReceiptCandidateDecisions | undefined {
  if (value === undefined) return;
  assertPlainRecord(value, label);
  assertOnlyKeys(value, RECEIPT_CANDIDATE_DECISIONS_KEYS, label);
  if (typeof value.complete !== "boolean") {
    throw new TypeError(`${label} complete must be a boolean`);
  }
  const decisions = value.decisions;
  if (!Array.isArray(decisions) || Object.getPrototypeOf(decisions) !== Array.prototype) {
    throw new TypeError(`${label} decisions must be an array`);
  }
  if (decisions.length > MAX_RECEIPT_CANDIDATE_DECISIONS) {
    throw new TypeError(`${label} decisions exceeds the maximum item count`);
  }
  const refs = new Set<string>();
  for (let index = 0; index < decisions.length; index += 1) {
    if (!Object.hasOwn(decisions, index)) {
      throw new TypeError(`${label} decisions must be a dense array`);
    }
    const decision = decisions[index];
    const decisionLabel = `${label} decision ${index}`;
    assertPlainRecord(decision, decisionLabel);
    assertOnlyKeys(decision, RECEIPT_CANDIDATE_DECISION_KEYS, decisionLabel);
    if (
      typeof decision.ref !== "string" ||
      decision.ref.length === 0 ||
      decision.ref.length > MAX_RECEIPT_REFERENCE_LENGTH ||
      !RECEIPT_REFERENCE_RE.test(decision.ref)
    ) {
      throw new TypeError(`${decisionLabel} ref must be a bounded canonical reference`);
    }
    if (refs.has(decision.ref)) throw new TypeError(`${label} decisions must use unique refs`);
    refs.add(decision.ref);
    if (
      typeof decision.sourceId !== "string" ||
      decision.sourceId.length === 0 ||
      decision.sourceId.length > MAX_RECEIPT_CANDIDATE_SOURCE_LENGTH ||
      !RECEIPT_ID_RE.test(decision.sourceId)
    ) {
      throw new TypeError(`${decisionLabel} sourceId must be a bounded public identifier`);
    }
    if (
      typeof decision.channel !== "string" ||
      !RECEIPT_CANDIDATE_CHANNEL_RE.test(decision.channel)
    ) {
      throw new TypeError(`${decisionLabel} channel must be a bounded public identifier`);
    }
    if (!RECEIPT_CANDIDATE_DISPOSITIONS.has(decision.disposition as ReceiptCandidateDisposition)) {
      throw new TypeError(`${decisionLabel} disposition is unsupported`);
    }
    if (!RECEIPT_CANDIDATE_REASONS.has(decision.reason as ReceiptCandidateReason)) {
      throw new TypeError(`${decisionLabel} reason is unsupported`);
    }
    assertNonNegativeInteger(decision.charsRequested, `${decisionLabel} charsRequested`);
    assertNonNegativeInteger(decision.charsApplied, `${decisionLabel} charsApplied`);
  }
  for (const key of Reflect.ownKeys(decisions)) {
    if (key === "length") continue;
    if (typeof key !== "string" || !/^(?:0|[1-9]\d*)$/.test(key) || Number(key) >= decisions.length) {
      throw new TypeError(`${label} decisions contains unsupported array field: ${String(key)}`);
    }
    const descriptor = Object.getOwnPropertyDescriptor(decisions, key);
    if (!descriptor?.enumerable || !("value" in descriptor)) {
      throw new TypeError(`${label} decisions entries must be enumerable data properties`);
    }
  }
}

function candidateDecisionsForJson(value: ReceiptCandidateDecisions | undefined): {
  complete: boolean;
  decisions: Array<{
    ref: string;
    sourceId: string;
    channel: string;
    disposition: ReceiptCandidateDisposition;
    reason: ReceiptCandidateReason;
    charsRequested: number;
    charsApplied: number;
  }>;
} | null {
  if (!value) return null;
  return {
    complete: value.complete,
    decisions: value.decisions.map((decision) => ({
      ref: decision.ref,
      sourceId: decision.sourceId,
      channel: decision.channel,
      disposition: decision.disposition,
      reason: decision.reason,
      charsRequested: decision.charsRequested,
      charsApplied: decision.charsApplied,
    })),
  };
}

function serializeCandidateDecisions(value: ReceiptCandidateDecisions | undefined): string | null {
  const normalized = candidateDecisionsForJson(value);
  return normalized ? JSON.stringify(normalized) : null;
}

function validatePutReceiptInput(input: PutReceiptInput): void {
  assertPlainRecord(input, "ReceiptStore.put input");
  assertOnlyKeys(input, PUT_RECEIPT_KEYS, "ReceiptStore.put input");
  if (
    typeof input.idempotencyKey !== "string" ||
    input.idempotencyKey.length === 0 ||
    input.idempotencyKey.length > MAX_IDEMPOTENCY_KEY_LENGTH ||
    !RECEIPT_ID_RE.test(input.idempotencyKey)
  ) {
    throw new TypeError("ReceiptStore.put idempotencyKey must be a bounded canonical identifier");
  }
  if (!RUNTIME_RECEIPT_KINDS.includes(input.kind))
    throw new TypeError(`unsupported receipt kind: ${String(input.kind)}`);
  if (input.version !== RECEIPT_VERSIONS[input.kind]) {
    throw new TypeError(`unsupported receipt version ${String(input.version)} for ${input.kind}`);
  }
  if (
    input.createdAt !== undefined &&
    (!Number.isSafeInteger(input.createdAt) || input.createdAt < 0)
  ) {
    throw new TypeError("receipt createdAt must be a non-negative safe integer");
  }

  assertPlainRecord(input.identity, "receipt identity");
  assertOnlyKeys(input.identity, RECEIPT_IDENTITY_KEYS, "receipt identity");
  for (const key of ["sessionKey", "runId", "traceId", "providerId", "adapterId"] as const) {
    assertOptionalId(
      input.identity[key],
      `receipt identity ${key}`,
      key === "sessionKey" ? RECEIPT_SESSION_KEY_RE : RECEIPT_ID_RE,
    );
  }
  assertCanonicalStringArray(input.identity.transformIds, "receipt identity transformIds", {
    maxItems: MAX_TRANSFORM_IDS,
    maxLength: MAX_TRANSFORM_ID_LENGTH,
    pattern: RECEIPT_ID_RE,
  });
  if (!RUNTIME_RECEIPT_RUNTIME_MODES.includes(input.identity.runtimeMode)) {
    throw new TypeError(`unsupported receipt runtime mode: ${String(input.identity.runtimeMode)}`);
  }
  if (input.kind !== "effect" && (!input.identity.providerId || !input.identity.adapterId)) {
    throw new TypeError("model receipt identity requires providerId and adapterId");
  }

  assertPlainRecord(input.callIndex, "receipt callIndex");
  assertOnlyKeys(input.callIndex, RECEIPT_CALL_INDEX_KEYS, "receipt callIndex");
  assertNonNegativeInteger(input.callIndex.attemptIndex, "receipt attemptIndex");
  assertNonNegativeInteger(input.callIndex.modelCallIndex, "receipt modelCallIndex");
  assertNonNegativeInteger(input.callIndex.wireAttemptIndex, "receipt wireAttemptIndex");

  assertPlainRecord(input.content, "receipt content");
  assertOnlyKeys(input.content, RECEIPT_CONTENT_KEYS, "receipt content");
  assertDigest(input.content.correlationDigest, "receipt content correlationDigest", true);
  assertDigest(
    input.content.logicalDigest,
    "receipt content logicalDigest",
    input.kind === "shadow_context" || input.kind === "context",
  );
  assertDigest(
    input.content.wireDigest,
    "receipt content wireDigest",
    input.kind === "shadow_wire" || input.kind === "wire",
  );
  assertDigest(input.content.policyDigest, "receipt content policyDigest", false);
  assertBudget(input.content.budget, "receipt content budget");
  assertCanonicalStringArray(input.content.selected, "receipt content selected", {
    maxItems: MAX_RECEIPT_REFERENCES,
    maxLength: MAX_RECEIPT_REFERENCE_LENGTH,
    pattern: RECEIPT_REFERENCE_RE,
  });
  assertCanonicalStringArray(input.content.omitted, "receipt content omitted", {
    maxItems: MAX_RECEIPT_REFERENCES,
    maxLength: MAX_RECEIPT_REFERENCE_LENGTH,
    pattern: RECEIPT_REFERENCE_RE,
  });
  assertCandidateDecisions(input.content.candidateDecisions, "receipt content candidateDecisions");
  const selected = new Set(input.content.selected ?? []);
  if ((input.content.omitted ?? []).some((reference) => selected.has(reference))) {
    throw new TypeError("receipt content selected and omitted references must be disjoint");
  }
}

export type DeleteReceiptPolicy = {
  /** Delete only receipts of these kinds (required; empty rejects the call). */
  kinds: RuntimeReceiptKind[];
  /** Delete only receipts older than now - maxAgeMs. */
  maxAgeMs: number;
  /** Hard upper bound; refuse a policy that could delete the whole table. */
  now?: number;
};

export type DeleteReceiptResult = { deleted: number };

function sha256Text(value: string): string {
  return createHash("sha256").update(value).digest("hex");
}

export function receiptContentDigest(
  identity: ReceiptIdentity,
  callIndex: ReceiptCallIndex,
  content: ReceiptContent,
): string {
  return sha256Text(
    JSON.stringify({
      identity: {
        sessionKey: identity.sessionKey ?? null,
        runId: identity.runId ?? null,
        traceId: identity.traceId ?? null,
        providerId: identity.providerId ?? null,
        adapterId: identity.adapterId ?? null,
        transformIds: identity.transformIds?.length ? identity.transformIds : null,
        runtimeMode: identity.runtimeMode,
      },
      callIndex: {
        attemptIndex: callIndex.attemptIndex,
        modelCallIndex: callIndex.modelCallIndex,
        wireAttemptIndex: callIndex.wireAttemptIndex,
      },
      content: {
        logicalDigest: content.logicalDigest ?? null,
        wireDigest: content.wireDigest ?? null,
        correlationDigest: content.correlationDigest,
        selected: content.selected?.length ? content.selected : null,
        omitted: content.omitted?.length ? content.omitted : null,
        candidateDecisions: candidateDecisionsForJson(content.candidateDecisions),
        budget: content.budget
          ? content.budget.unit === "chars"
            ? {
                unit: content.budget.unit,
                charsRequested: content.budget.charsRequested,
                charsApplied: content.budget.charsApplied,
              }
            : {
                unit: content.budget.unit,
                inputLimit: content.budget.inputLimit,
                outputLimit: content.budget.outputLimit,
              }
          : null,
        policyDigest: content.policyDigest ?? null,
      },
    }),
  );
}

/**
 * Narrow ReceiptStore: append-only put with content-sensitive idempotency, typed
 * queries, and an explicit lifecycle-policy delete. Writes go through the shared
 * openclaw-state immediate transaction so they are durable and atomic.
 */
export class ReceiptStore {
  #database: OpenClawStateDatabaseOptions = {};

  constructor(options: OpenClawStateDatabaseOptions = {}) {
    this.#database = options;
  }

  /** Append a receipt. Validation/storage errors propagate to the caller;
   *  shadow callers catch them and record failed evidence without changing
   *  send behavior. */
  put(input: PutReceiptInput): PutReceiptResult {
    validatePutReceiptInput(input);
    // The digest is an internal fact. Callers cannot forge it or influence the
    // idempotency comparison by supplying a precomputed value.
    const contentDigest = receiptContentDigest(input.identity, input.callIndex, input.content);
    let outcome: PutReceiptResult | undefined;
    runOpenClawStateWriteTransaction(({ db }) => {
      const query = getNodeSqliteKysely<RuntimeReceiptDatabase>(db);
      const existing = executeSqliteQueryTakeFirstSync(
        db,
        query
          .selectFrom("runtime_receipts")
          .selectAll()
          .where("idempotency_key", "=", input.idempotencyKey),
      );
      if (existing) {
        // Kind/version are stored outside the stable content digest. A key
        // collision must not turn one receipt type into evidence for another.
        if (
          existing.kind === input.kind &&
          existing.version === input.version &&
          existing.content_digest === contentDigest
        ) {
          outcome = {
            ok: true,
            duplicate: true,
            receiptId: existing.receipt_id,
            inserted: false,
            reason: "identical-content",
          };
          return;
        }
        outcome = {
          ok: false,
          duplicate: true,
          receiptId: existing.receipt_id,
          inserted: false,
          reason: "content-conflict",
          existing: existing.content_digest,
        };
        return;
      }
      const receiptId = `rcpt_${randomUUID()}`;
      const row: RuntimeReceiptInsert = {
        receipt_id: receiptId,
        idempotency_key: input.idempotencyKey,
        kind: input.kind,
        runtime_mode: input.identity.runtimeMode,
        version: input.version,
        session_key: input.identity.sessionKey ?? null,
        run_id: input.identity.runId ?? null,
        trace_id: input.identity.traceId ?? null,
        attempt_index: input.callIndex.attemptIndex,
        model_call_index: input.callIndex.modelCallIndex,
        wire_attempt_index: input.callIndex.wireAttemptIndex,
        provider_id: input.identity.providerId ?? null,
        adapter_id: input.identity.adapterId ?? null,
        transform_ids_json: input.identity.transformIds?.length
          ? JSON.stringify(input.identity.transformIds)
          : null,
        selected_json: input.content.selected?.length
          ? JSON.stringify(input.content.selected)
          : null,
        omitted_json: input.content.omitted?.length ? JSON.stringify(input.content.omitted) : null,
        candidate_decisions_json: serializeCandidateDecisions(input.content.candidateDecisions),
        budget_json: serializeBudget(input.content.budget),
        policy_digest: input.content.policyDigest ?? null,
        logical_digest: input.content.logicalDigest ?? null,
        wire_digest: input.content.wireDigest ?? null,
        correlation_digest: input.content.correlationDigest,
        content_digest: contentDigest,
        created_at: input.createdAt ?? Date.now(),
      };
      executeSqliteQuerySync(db, query.insertInto("runtime_receipts").values(row));
      outcome = { ok: true, duplicate: false, receiptId, inserted: true };
    }, this.#database);
    if (!outcome) {
      throw new Error("ReceiptStore.put did not complete a transaction outcome");
    }
    return outcome;
  }

  /** Get one receipt by idempotency key. */
  getByIdempotencyKey(idempotencyKey: string): RuntimeReceiptRow | undefined {
    const { db } = openOpenClawStateDatabase(this.#database);
    const query = getNodeSqliteKysely<RuntimeReceiptDatabase>(db);
    return executeSqliteQueryTakeFirstSync(
      db,
      query
        .selectFrom("runtime_receipts")
        .selectAll()
        .where("idempotency_key", "=", idempotencyKey),
    );
  }

  /** Query receipts by kind, optionally scoped to a run, attempt/call indexes, or correlation digest. */
  list(
    options: {
      kind?: RuntimeReceiptKind;
      runId?: string;
      attemptIndex?: number;
      modelCallIndex?: number;
      correlationDigest?: string;
      limit?: number;
    } = {},
  ): RuntimeReceiptRow[] {
    const { db } = openOpenClawStateDatabase(this.#database);
    const query = getNodeSqliteKysely<RuntimeReceiptDatabase>(db);
    let builder = query.selectFrom("runtime_receipts").selectAll();
    if (options.kind) builder = builder.where("kind", "=", options.kind);
    if (options.runId) builder = builder.where("run_id", "=", options.runId);
    if (options.attemptIndex !== undefined)
      builder = builder.where("attempt_index", "=", options.attemptIndex);
    if (options.modelCallIndex !== undefined)
      builder = builder.where("model_call_index", "=", options.modelCallIndex);
    if (options.correlationDigest)
      builder = builder.where("correlation_digest", "=", options.correlationDigest);
    builder = builder.orderBy("created_at", "desc");
    if (options.limit) builder = builder.limit(options.limit);
    return executeSqliteQuerySync<RuntimeReceiptRow>(db, builder).rows;
  }

  /**
   * R5-3: join v1 ContextReceipt and WireReceipt rows that share one
   * correlation_digest. Returns only complete pairs; no new table.
   */
  joinByCorrelation(
    options: {
      runId?: string;
      correlationDigest?: string;
      limit?: number;
    } = {},
  ): RuntimeReceiptPair[] {
    const { db } = openOpenClawStateDatabase(this.#database);
    const query = getNodeSqliteKysely<RuntimeReceiptDatabase>(db);
    let builder = query
      .selectFrom("runtime_receipts")
      .selectAll()
      .where("kind", "in", ["context", "wire"] as const)
      .where("version", "=", "1");
    if (options.runId) builder = builder.where("run_id", "=", options.runId);
    if (options.correlationDigest)
      builder = builder.where("correlation_digest", "=", options.correlationDigest);
    builder = builder.orderBy("created_at", "desc");
    if (options.limit) builder = builder.limit(options.limit);
    const rows = executeSqliteQuerySync<RuntimeReceiptRow>(db, builder).rows;
    const byCorrelation = new Map<
      string,
      { context?: RuntimeReceiptRow; wire?: RuntimeReceiptRow }
    >();
    for (const row of rows) {
      const digest = row.correlation_digest;
      if (!digest) continue;
      const entry = byCorrelation.get(digest) ?? {};
      if (row.kind === "context" && !entry.context) entry.context = row;
      if (row.kind === "wire" && !entry.wire) entry.wire = row;
      byCorrelation.set(digest, entry);
    }
    return [...byCorrelation.entries()]
      .filter(([, entry]) => entry.context !== undefined && entry.wire !== undefined)
      .map(([correlationDigest, entry]) => ({
        correlationDigest,
        context: entry.context!,
        wire: entry.wire!,
      }));
  }

  /**
   * Explicit lifecycle-policy delete. Refuses empty kind lists and unbounded
   * age so no silent pruning is possible. Returns the number of deleted rows.
   */
  deleteByPolicy(policy: DeleteReceiptPolicy): DeleteReceiptResult {
    if (!policy.kinds.length) throw new Error("deleteByPolicy requires at least one receipt kind");
    if (!Number.isFinite(policy.maxAgeMs) || policy.maxAgeMs <= 0) {
      throw new Error("deleteByPolicy requires a positive maxAgeMs");
    }
    let deleted = 0;
    const now = policy.now ?? Date.now();
    const cutoff = now - policy.maxAgeMs;
    runOpenClawStateWriteTransaction(({ db }) => {
      const query = getNodeSqliteKysely<RuntimeReceiptDatabase>(db);
      const builder = query
        .deleteFrom("runtime_receipts")
        .where("created_at", "<", cutoff)
        .where("kind", "in", policy.kinds);
      const result = executeSqliteQuerySync(db, builder);
      deleted = Number(result.numAffectedRows ?? 0n);
    }, this.#database);
    return { deleted };
  }

  /** Drop all rows; for test isolation only, never used by runtime code. */
  clearForTest(): void {
    runOpenClawStateWriteTransaction(({ db }) => {
      const query = getNodeSqliteKysely<RuntimeReceiptDatabase>(db);
      executeSqliteQuerySync(db, query.deleteFrom("runtime_receipts"));
    }, this.#database);
  }
}

